mapper.select:
SELECT t.contract_id, t.cashflow_id, t.times, t.cf_type, t.cf_item, t.due_date WRITE_OFF_DATE, t.due_amount-nvl(t.received_amount,0) WRITE_OFF_DUE_AMOUNT, t.principal-nvl(t.received_principal,0) WRITE_OFF_PRINCIPAL, t.interest-nvl(t.received_interest,0) WRITE_OFF_INTEREST, c.deposit_deduction, c.CONTRACT_NUMBER FROM con_contract_cashflow t, con_contract c
c.contract_id = t.contract_id AND c.data_class = 'NORMAL' AND c.contract_status in ('INCEPT','ET') AND t.cf_status = 'RELEASE' AND nvl(t.WRITE_OFF_FLAG, 'NOT') IN ('PARTIAL', 'NOT') AND nvl(t.RECEIVED_AMOUNT, 0) < t.DUE_AMOUNT
and t.cf_item = #{cfItem}
and exists(select 1 from con_contract_cashflow cw where cw.contract_id = c.contract_id and cw.cf_item = 1 and cw.times = t.times-1 AND nvl(cw.WRITE_OFF_FLAG, 'NOT') = 'FULL') and t.cf_item = 52 and t.cf_direction = 'OUTFLOW'
and t.times = #{times}
and t.contract_id = #{contractId}
order by c.contract_id,t.times

SELECT t.* FROM ( SELECT ( SELECT ct.TRANSACTION_NUM FROM CSH_TRANSACTION ct WHERE ct.TRANSACTION_ID = t.CSH_TRANSACTION_ID ) TRANSACTION_NUM, ( SELECT TO_CHAR ( ct.TRANSACTION_DATE, 'YYYY-MM-DD' ) FROM CSH_TRANSACTION ct WHERE ct.TRANSACTION_ID = t.CSH_TRANSACTION_ID ) TRANSACTION_DATE, ( SELECT ct.TRANSACTION_AMOUNT FROM CSH_TRANSACTION ct WHERE ct.TRANSACTION_ID = t.CSH_TRANSACTION_ID ) TRANSACTION_AMOUNT, (select ccc.due_date from CON_CONTRACT_CASHFLOW ccc where t.CASHFLOW_ID=ccc.CASHFLOW_ID) due_date,
(select ccc.due_amount from CON_CONTRACT_CASHFLOW ccc where t.CASHFLOW_ID=ccc.CASHFLOW_ID) due_amount, ( SELECT cba.BANK_ACCOUNT_NUM FROM CSH_TRANSACTION ct, CSH_BANK_ACCOUNT cba WHERE ct.TRANSACTION_ID = t.CSH_TRANSACTION_ID AND ct.BANK_ACCOUNT_ID = cba.BANK_ACCOUNT_ID ) BANK_ACCOUNT_NUM, ( SELECT cc.VIRTUAL_ACCOUNT_NUM FROM con_contract cc WHERE cc.contract_id = t.contract_id ) REF_V01, ( SELECT cc.contract_number FROM con_contract cc WHERE cc.contract_id = t.contract_id ) contract_number, ( SELECT hbm.bp_name FROM con_contract cc, hls_bp_master hbm WHERE cc.contract_id = t.contract_id AND cc.tenant_id = hbm.bp_id ) BP_ID_TENANT_N, t.WRITE_OFF_TYPE, ( SELECT scvb.meaning FROM SYS_CODE_B scb, SYS_CODE_VALUE_B scvb WHERE scb.CODE = 'CSH301_WRITE_OFF_TYPE' AND scb.code_id = scvb.code_id AND scvb. VALUE = t.WRITE_OFF_TYPE ) AS WRITE_OFF_TYPE_N, t.WRITE_OFF_DATE, t.WRITE_OFF_DUE_AMOUNT, t.TIMES, t.CF_ITEM, ( SELECT hci.DESCRIPTION FROM HLS_CASHFLOW_ITEM hci WHERE hci.CF_ITEM = t.CF_ITEM ) AS CF_ITEM_N, ( SELECT hbm.bp_name FROM CSH_TRANSACTION ct, hls_bp_master hbm WHERE ct.TRANSACTION_ID = t.CSH_TRANSACTION_ID AND ct.bp_id = hbm.bp_id ) BP_NAME, t.ARRIVE_MODALITY, ( SELECT scvb.MEANING FROM SYS_CODE_B scb, SYS_CODE_VALUE_B scvb WHERE scb.CODE = 'CSH001_ARRIVE_MODALITY' AND scb.CODE_ID = scvb.CODE_ID AND scvb. VALUE = t.ARRIVE_MODALITY ) ARRIVE_MODALITY_DESC, ( SELECT ct.BP_BANK_ACCOUNT_NAME FROM CSH_TRANSACTION ct WHERE ct.TRANSACTION_ID = t.CSH_TRANSACTION_ID ) BP_BANK_ACCOUNT_NAME FROM CSH_WRITE_OFF t ) t
t.TRANSACTION_NUM is not null and t.contract_number like '%PRJ%' and t.WRITE_OFF_TYPE in ('ADVANCE_RECEIPT_CREDIT','RECEIPT_ADVANCE_RECEIPT','RECEIPT_CREDIT','RECEIPT_DEPOSIT')
AND t.TRANSACTION_NUM like concat(concat('%',#{transactionNum}),'%')
AND t.TRANSACTION_AMOUNT >= #{transactionAmountFrom}
AND t.TRANSACTION_AMOUNT <= #{transactionAmountTo}
AND t.BANK_ACCOUNT_NUM like concat(concat('%',#{bankAccountNum}),'%')
AND t.REF_V01 like concat(concat('%',#{refV01}),'%')
AND t.CONTRACT_NUMBER like concat(concat('%',#{contractNumber}),'%')
AND t.BP_ID_TENANT_N like concat(concat('%',#{bpIdTenantN}),'%')
AND t.WRITE_OFF_TYPE = #{writeOffType}
AND t.CF_ITEM = #{cfItem}
AND t.BP_NAME like concat(concat('%',#{bpName}),'%')
AND t.BP_BANK_ACCOUNT_NAME like concat(concat('%',#{bpBankAccountName}),'%')
AND t.ARRIVE_MODALITY = #{arriveModality}
